<tr><td>Section 438 CrPC</td><td>Anticipatory bail</td><td>Section 482 BNSS</td></tr>
<tr><td>Section 438(2) CrPC conditions</td><td>Cooperation, no tampering, travel restriction</td><td>Section 482(2) BNSS</td></tr>
